      background: var(--bg); border-top: 1px solid var(--border);
      padding: 80px 0 40px;
    }
    .footer-top {
      display: grid; grid-template-columns: 1fr 1fr; gap: 80px;
      padding-bottom: 60px; border-bottom: 1px solid var(--border); margin-bottom: 48px;
    }
    .footer-cta-block {}
