    .footer-legal-link:hover { color: var(--text); }

    /* ─── Cookie Banner ──────────────────────────────── */
    .cookie-banner {
      position: fixed; bottom: 24px; left: 24px; right: 24px;
      max-width: 640px; margin: 0 auto;
      background: var(--bg3); border: 1px solid rgba(255,255,255,0.12);
      border-radius: 4px; padding: 24px 28px; z-index: 200;
      box-shadow: 0 24px 48px rgba(0,0,0,0.4);
      display: flex; flex-direction: column; gap: 16px;
      animation: slideUp 0.4s ease;
    }
    .cookie-banner.hidden { display: none; }
    @keyframes slideUp {
      from { transform: translateY(20px); opacity: 0; }
      to { transform: translateY(0); opacity: 1; }
    }
    .cookie-title { font-family: var(--font-d); font-size: 16px; font-weight: 700; }
    .cookie-body { font-size: 13px; color: var(--text-2); line-height: 1.6; }
