# Quick HTML validation - check for unclosed tags, balanced structure
python3 -c "
from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void: return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'Unexpected </{tag}>, stack top: {self.stack[-1] if self.stack else \"empty\"}')

v = Validator()
with open('/app/output/index.html') as f:
    v.feed(f.read())
if v.errors:
    print('ERRORS:', v.errors[:5])
elif v.stack:
    print('Unclosed:', v.stack[-10:])
else:
    print('HTML structure OK')
"

